function closeModal(){stopWebMonitor();if(modal.value==='login')void invoke('close_web_login').catch(()=>{});modal.value='';loginGeneration++;if(poll)clearTimeout(poll)}
function showLogin(){modal.value='login';loginMethod.value='web';webHint.value='';qrSvg.value='';loginGeneration++;if(poll)clearTimeout(poll)}
function chooseLogin(method:'web'|'qr'){stopWebMonitor();loginGeneration++;if(poll)clearTimeout(poll);loginMethod.value=method;webHint.value='';void invoke('close_web_login').catch(()=>{});if(method==='qr')void startLogin()}
async function openWebLogin(){webBusy.value=true;try{await invoke('open_web_login');webHint.value='请在官方窗口完成登录，成功后窗口将自动关闭并连接账号。';monitorWebLogin()}catch(e){webHint.value=String(e)}finally{webBusy.value=false}}
async function doSearch(text=query.value){text=text.trim();if(!text)return;query.value=text;searchHistory.value=[text,...searchHistory.value.filter(word=>word.toLowerCase()!==text.toLowerCase())].slice(0,20);if(verificationRequired.value){verificationKeyword.value=text;notify('BILIBILI_VERIFICATION_REQUIRED: 请先完成 B 站安全验证，再重新搜索。');return}query.value=text;view.value='search';searching.value=true;searched.value=true;const generation=++searchGeneration;try{const data=await invoke<Track[]>('search',{keyword:text});if(generation===searchGeneration)results.value=data}catch(e){if(generation===searchGeneration){results.value=[];notify(e)}}finally{if(generation===searchGeneration)searching.value=false}}
function add(t:Track){if(!active.value.tracks.some(x=>x.id===t.id)){active.value.tracks.push({...t});}else notify('这首歌已经在当前歌单里了')}
function selectResult(t:Track){if(target.value){const original=target.value;for(const p of lists.value){p.tracks=p.tracks.map(x=>x.id===original.id?{...x,bvid:t.bvid,cover:t.cover,duration:t.duration,artist:x.artist||t.artist,matchStatus:'manual' as const,matchScore:undefined,matchReason:'用户手动选择',candidates:[]}:x)}target.value=null;notify('已为歌曲关联 B 站音源，返回歌单即可播放')}else add(t)}
function findSource(t:Track){sourceTarget.value=t;modal.value='source';closeMenus()}
async function play(t:Track,list=rows.value,keepQueue=false){
 checkpointQueue();let entry:QueueEntry<Track>|undefined
 if(keepQueue){entry=queueEntries.value.find(e=>e.entryId===currentQueue.value?.cursorId&&e.track.id===t.id)||queueEntries.value.find(e=>e.track.id===t.id);if(entry)return startEntry(entry,t)}
 if(insertOnClick.value&&currentQueue.value?.entries.length)entry=insertEntry(currentQueue.value,t)
 else entry=replaceQueue(t,list)
 return startEntry(entry)
}
async function playPlaylist(){if(!rows.value.length)return notify('歌单还是空的，先添加一些音乐吧');const entry=replaceQueue(rows.value[0],rows.value);await startEntry(entry)}
async function startEntry(entry:QueueEntry<Track>,override?:Track){
 checkpointQueue();const session=queueSessions.value.find(s=>s.entries.some(e=>e.entryId===entry.entryId));if(!session)return
 const generation=++playbackGeneration;loading.value=true;playing.value=false;audio.value?.pause();if(audio.value){audio.value.removeAttribute('src');audio.value.load()}
 activeQueueId.value=session.id;session.cursorId=entry.entryId;session.updatedAt=Date.now();playbackMode.value=session.mode
 const t=override||hydrateTrack(entry.track);current.value=t;const position=startupResumePending&&entry.entryId===startupEntryId&&!restoreProgress.value?0:resumePosition(session.positions[entry.entryId],trackSeconds(t));elapsed.value=position;duration.value=trackSeconds(t);let resume:(()=>void)|undefined
 try{if(sound){sound.setEnabled(balanceEnabled.value);sound.setTrackGain(trackGainDb.value);await sound.resume();sound.reset()}await ensureSource(t);if(generation!==playbackGeneration)return;if(!override)entry.track={...t};const raw=t.url?{url:t.url}:await invoke<{url:string}>('resolve',{bvid:t.bvid});if(generation!==playbackGeneration||!audio.value)return;resume=()=>{if(generation===playbackGeneration&&audio.value&&Number.isFinite(audio.value.duration))audio.value.currentTime=resumePosition(position,audio.value.duration)};audio.value.addEventListener('loadedmetadata',resume,{once:true});audio.value.src=raw.url;audio.value.load();await audio.value.play();if(generation!==playbackGeneration)return;hasStartedPlayback=true;startupResumePending=false;history.value=[{...t},...history.value.filter(x=>x.id!==t.id)].slice(0,100)}catch(e){if(generation===playbackGeneration)notify(e)}finally{if(resume)audio.value?.removeEventListener('loadedmetadata',resume);if(generation===playbackGeneration){loading.value=false;checkpointQueue();void flushQueue().catch(notify)}}
}
async function toggle(){if(!current.value){if(rows.value[0])await play(rows.value[0]);else notify('先搜索一首歌，或导入本地音乐');return}if(!audio.value?.src)return play(current.value,queue.value,true);try{if(audio.value.paused){await sound?.resume();await audio.value.play();}else audio.value.pause()}catch(e){notify(e)}}
function next(delta=1,automatic=false){const session=currentQueue.value;if(!session)return;if(delta===1&&session.pending.length){const id=session.pending.shift()!;const entry=session.entries.find(e=>e.entryId===id);if(entry){void startEntry(entry);return}}const i=session.entries.findIndex(e=>e.entryId===session.cursorId);const at=nextIndex(session.entries.length,i,playbackMode.value,delta,automatic);if(at<0){audio.value?.pause();checkpointQueue();return}void startEntry(session.entries[at])}
function ended(){if(playbackMode.value==='single'&&!currentQueue.value?.pending.length&&audio.value){audio.value.currentTime=0;void audio.value.play().catch(notify)}else next(1,true)}
function like(t=current.value){if(!t)return;const fav=lists.value[0].tracks;const i=fav.findIndex(x=>x.id===t.id);if(i<0)fav.push({...t});else fav.splice(i,1)}
function seek(e:Event){seekSeconds(Number((e.target as HTMLInputElement).value))}
function createList(){if(!newName.value.trim())return;const p={id:crypto.randomUUID(),name:newName.value.trim(),tracks:[]};lists.value.push(p);openList(p);newName.value='';closeModal()}
function removeTrack(t:Track){active.value.tracks=active.value.tracks.filter(x=>x.id!==t.id)}
function deleteList(){if(selected.value==='favorites')return;lists.value=lists.value.filter(x=>x.id!==selected.value);selected.value='favorites';view.value='playlist';closeModal()}
async function importSongs(){if(!importValue.value.trim())return;importing.value=true;try{let tracks:Track[];if(importMode.value==='link'){const imported=await invoke<{name:string;tracks:Track[];total:number}>('import_kugou',{input:importValue.value});tracks=imported.tracks;if(!importName.value.trim())importName.value=imported.name}else{tracks=importValue.value.split('\n').map(x=>x.trim()).filter(Boolean).map(line=>{const parts=line.split(/\s+-\s+/);return{id:crypto.randomUUID(),title:parts.length>1?parts.slice(1).join(' - '):line,artist:parts.length>1?parts[0]:'',source:'text'}})}if(!tracks.length)throw new Error('没有读到歌曲，请检查输入');const p={id:crypto.randomUUID(),name:importName.value.trim()||'新导入的歌单',tracks};if(matching.value)cancelMatching();lists.value.push(p);openList(p);closeModal();importValue.value='';importName.value='';if(!matching.value)void matchPlaylist(p.id)}catch(e){notify(e)}finally{importing.value=false}}
function localFiles(e:Event){const files=(e.target as HTMLInputElement).files;if(!files)return;const tracks=Array.from(files).filter(f=>/\.(mp3|m4a|wav|ogg|flac|aac)$/i.test(f.name)).map(f=>{const url=URL.createObjectURL(f);localUrls.push(url);const title=f.name.replace(/\.[^.]+$/,'');const saved=queueSessions.value.flatMap(s=>s.entries).find(e=>e.track.source==='local'&&e.track.title===title&&(e.track.localFileSize===undefined||e.track.localFileSize===f.size));const track={id:saved?.track.id||crypto.randomUUID(),title,artist:'本地音乐 · 本次会话',source:'local',url,localFileSize:f.size};for(const s of queueSessions.value)for(const e of s.entries)if(e.track.id===track.id)Object.assign(e.track,track);return track});for(const track of tracks){const previous=active.value.tracks.find(t=>t.id===track.id);if(previous)Object.assign(previous,track);else active.value.tracks.push(track)}view.value='playlist';if(tracks.length===0)notify('请选择 MP3、M4A、WAV、OGG、FLAC 或 AAC 音频');(e.target as HTMLInputElement).value=''}
async function refreshAccount(){try{user.value=await invoke('account')}catch{user.value=null}}
async function startLogin(){modal.value='login';qrSvg.value='';qrBusy.value=true;qrHint.value='正在生成二维码…';if(poll)clearTimeout(poll);const generation=++loginGeneration;try{const qr=await invoke<{key:string;svg:string}>('login_qr');if(generation!==loginGeneration)return;qrSvg.value=qr.svg;qrHint.value='使用哔哩哔哩 App 扫码登录';const tick=async()=>{try{const d=await invoke<{code:number;message:string}>('login_poll',{key:qr.key});if(generation!==loginGeneration||!alive)return;if(d.code===0){await refreshAccount();closeModal();return}if(d.code===86038){qrHint.value='二维码已过期，请刷新';return}qrHint.value=d.code===86090?'已扫码，请在手机上确认':'使用哔哩哔哩 App 扫码登录';poll=setTimeout(tick,2200)}catch(e){if(generation===loginGeneration){qrHint.value='连接中断，请刷新重试';notify(e)}}};poll=setTimeout(tick,2200)}catch(e){if(generation===loginGeneration){qrHint.value='二维码获取失败';notify(e)}}finally{if(generation===loginGeneration)qrBusy.value=false}}
async function signOut(){try{await invoke('logout');user.value=null;closeModal()}catch(e){notify(e)}}
function keyboard(e:KeyboardEvent){if(e.key==='Escape'){closeMenus();if(modal.value&&!importing.value)closeModal();else detailsOpen.value=false;return}if((e.target as HTMLElement)?.closest('input,textarea,button')||modal.value)return;if(e.code==='Space'){e.preventDefault();void toggle()}}
watch(volume,v=>{if(sound)sound.setVolume(v);else if(audio.value)audio.value.volume=v})
watch([queueSessions,activeQueueId,insertOnClick,restoreProgress],scheduleQueueSave,{deep:true})
watch(restoreProgress,()=>{if(startupResumePending)elapsed.value=restoreProgress.value?resumePosition(currentQueue.value?.positions[startupEntryId],duration.value):0})
watch(playbackMode,mode=>{if(currentQueue.value)currentQueue.value.mode=mode})
watch(balanceEnabled,v=>sound?.setEnabled(v),{flush:'sync'})
watch(trackGainDb,v=>sound?.setTrackGain(v),{flush:'sync'})
watch(theme,applyTheme)
watch(volume,v=>{volumeDraft.value=String(Math.round(v*100))})
watch(user,value=>{if(value)resumeUnmatched(selected.value);else if(matching.value)cancelMatching()})
watch([lists,history,searchHistory,view,selected,volume,playbackMode,verificationRequired,verificationKeyword,theme,defaultBalanceEnabled,trackAudioSettings],()=>{if(!ready.value)return;const payload=JSON.parse(JSON.stringify({schemaVersion:1,searchHistory:searchHistory.value,trackAudioSettings:trackAudioSettings.value,preferences:{volume:volume.value,playbackMode:playbackMode.value,theme:theme.value,balanceEnabled:defaultBalanceEnabled.value,lastView:view.value,lastPlaylistId:selected.value,needsVerification:verificationRequired.value,verificationKeyword:verificationKeyword.value},lists:lists.value.map(p=>({...p,tracks:p.tracks.filter(t=>t.source!=='local')})),history:history.value.filter(t=>t.source!=='local')}));persist=persist.then(()=>invoke<void>('save_library',{value:payload})).catch(e=>notify(`保存失败：${e}`))},{deep:true})
onMounted(async()=>{window.addEventListener('keydown',keyboard);window.addEventListener('click',closeMenus);window.addEventListener('resize',closeMenus);applyTheme(theme.value);if(audio.value){sound=new AudioBalance(audio.value,db=>balanceDb.value=db);sound.setVolume(volume.value);sound.setEnabled(balanceEnabled.value);sound.setTrackGain(trackGainDb.value)}try{const data=await invoke<{lists:Playlist[];history:Track[];searchHistory?:string[];trackAudioSettings?:unknown;preferences?:{volume:number;playbackMode:PlaybackMode;lastView?:string;lastPlaylistId?:string;theme?:ThemeId;balanceEnabled?:boolean;needsVerification?:boolean;verificationKeyword?:string}}|null>('load_library');if(data?.lists?.length){lists.value=data.lists;trackAudioSettings.value=readTrackAudioSettings(data.trackAudioSettings);searchHistory.value=(data.searchHistory||[]).filter(word=>typeof word==='string').slice(0,20);history.value=data.history??[];if(data.preferences){if(data.preferences.lastPlaylistId&&lists.value.some(p=>p.id===data.preferences?.lastPlaylistId))selected.value=data.preferences.lastPlaylistId;if(['home','playlist','recent','search'].includes(data.preferences.lastView||''))view.value=data.preferences.lastView!;if(view.value==='search')query.value=searchHistory.value[0]||'';if(themes.some(t=>t.id===data.preferences?.theme))theme.value=data.preferences.theme!;if(typeof data.preferences.balanceEnabled==='boolean')defaultBalanceEnabled.value=data.preferences.balanceEnabled;if(data.preferences.needsVerification){verificationRequired.value=true;verificationHint.value='请先完成 B 站官方安全验证，恢复搜索后会继续匹配。';if(data.preferences.verificationKeyword)verificationKeyword.value=data.preferences.verificationKeyword}if(Number.isFinite(data.preferences.volume))volume.value=Math.max(0,Math.min(1,data.preferences.volume));if(modes.some(m=>m.value===data.preferences?.playbackMode))playbackMode.value=data.preferences.playbackMode}migrateSources()}ready.value=true}catch(e){ready.value=false;notify(`读取音乐库失败，已停止自动覆盖：${e}`)}await loadQueues();if(!alive)return;void watchWindowClose();void refreshAccount();try{const windows=await getAllWebviewWindows();if(windows.some(w=>w.label==='bilibili-login')&&!modal.value){showLogin();webHint.value='正在自动检测登录，成功后窗口将自动关闭。';monitorWebLogin()}}catch{} })
onUnmounted(()=>{checkpointQueue();void flushQueue().catch(()=>{});unlistenClose?.();if(queueSaveTimer)clearTimeout(queueSaveTimer);sound?.dispose();matchingGeneration++;stopWebMonitor();alive=false;loginGeneration++;if(poll)clearTimeout(poll);window.removeEventListener('keydown',keyboard);window.removeEventListener('click',closeMenus);window.removeEventListener('resize',closeMenus);for(const url of localUrls)URL.revokeObjectURL(url)})
</script>

