     <div v-if="view==='search'" class="search-intro"><SearchInput v-model="query" wide label="发现音乐搜索" :history="searchHistory" :library="searchLibrary" :busy="searching" @search="text=>{target=null;doSearch(text)}" @clear-history="searchHistory=[]"/><div class="search-tips"><span>试试搜索</span><button v-for="word in ['纯音乐','爵士钢琴','日落 城市 音乐']" @click="target=null;doSearch(word)">{{word}}</button><button v-if="target" @click="target=null">取消关联音源</button></div></div>
     <div class="table-toolbar"><span>{{view==='search'?'搜索结果':'歌曲列表'}} <small>{{rows.length}}</small></span><span>{{view==='search'?`添加到：${active.name}`: '点击歌曲开始聆听'}}</span></div>
