     <template v-else-if="rows.length">
      <div class="track-header"><span>#</span><span>歌曲 / 视频</span><span>歌手 / UP 主</span><span>来源</span><span>时长</span><span>操作</span></div>
      <div v-for="(t,i) in rows" :key="t.id" :class="['track-row',{selected:current?.id===t.id}]" tabindex="0" @click="play(t)" @keydown.enter.prevent="play(t)" @contextmenu="openContext($event,t)">
       <button class="track-index" :title="`播放 ${t.title}`" @click.stop="play(t)"><AudioLines v-if="current?.id===t.id&&playing" :size="17"/><span v-else>{{String(i+1).padStart(2,'0')}}</span><Play class="row-play" :size="15"/></button>
       <div class="track-title"><div class="track-cover"><img v-if="t.cover" :src="t.cover" referrerpolicy="no-referrer" loading="lazy"/><span v-else>{{initial(t)}}</span></div><div><strong>{{t.title}}</strong><small :title="t.matchReason">{{t.source==='local'?'本地音乐':t.bvid?(t.matchStatus==='manual'?`已选歌源 · ${t.matchScore??'—'} 分`:t.matchScore!==undefined?`默认歌源 · 综合 ${t.matchScore} 分`:t.bvid):t.matchStatus==='review'?'暂无候选，可右键更换歌源':t.matchStatus==='failed'?(t.matchReason?.includes('BILIBILI_VERIFICATION_REQUIRED')?'等待 B 站安全验证':'搜索请求失败，可重试'):matching&&matchingList===active.id?(matchingCurrent===t.id?'正在匹配…':'排队匹配中'):'点击即匹配并播放'}}</small></div></div>
       <span class="artist">{{t.artist||'未知歌手'}}</span><span class="source-badge">{{t.bvid?'B 站':t.source==='local'?'本地':t.source==='kugou'?'酷狗':'清单'}}</span><span class="track-duration">{{t.duration||'—'}}</span>
       <div class="row-actions" @click.stop @keydown.enter.stop><button title="下一首播放" @click="queueNext(t)"><ListPlus :size="17"/></button><button title="加入歌单" @click="openAdd(t)"><Plus :size="17"/></button><button title="更多操作" @click.stop="openContext($event,t)"><MoreHorizontal :size="18"/></button></div>
      </div>
     </template>
     <div v-else class="empty"><span class="empty-icon"><Search v-if="view==='search'" :size="32"/><Music2 v-else :size="32"/></span><h3>{{view==='search'?(verificationRequired?'搜索暂停，请先完成 B 站验证':searched?'暂时没有找到结果':'下一首喜欢，正在等你'):view==='recent'?'留下一点音乐的足迹':'你的歌单，等一个开始'}}</h3><p>{{view==='search'?'试试更短的歌名，或者换一个关键词。':view==='recent'?'播放过的在线歌曲会保存在这里。':'导入歌曲清单、添加本地音乐，或去 B 站寻找好声音。'}}</p><button v-if="view!=='search'" class="secondary" @click="view==='recent'?view='search':modal='import'">{{view==='recent'?'发现音乐':'导入歌单'}}<ChevronRight :size="15"/></button></div>
    </template>
   </div>
  </main>
  <div v-if="contextMenu" class="track-menu" :style="{left:contextMenu.x+'px',top:contextMenu.y+'px'}" role="menu" @click.stop><strong>{{contextMenu.track.title}}</strong><button role="menuitem" @click="playContext"><Play :size="16"/>立即播放</button><button role="menuitem" :disabled="!!contextMenu.entryId&&contextMenu.entryId===currentQueue?.cursorId" @click="nextContext"><ListPlus :size="16"/>下一首播放</button><button role="menuitem" @click="openAdd(contextMenu.track)"><Plus :size="16"/>加入歌单</button><button v-if="contextMenu.track.source!=='local'" role="menuitem" @click="findSource(contextMenu.track)"><Radio :size="16"/>更换歌源</button><template v-if="contextMenu.entryId"><div class="menu-divider"/><button role="menuitem" :disabled="contextMoveDisabled('up')" @click="moveContext('up')"><ArrowUp :size="16"/>上移一位</button><button role="menuitem" :disabled="contextMoveDisabled('down')" @click="moveContext('down')"><ArrowDown :size="16"/>下移一位</button><button role="menuitem" :disabled="contextMoveDisabled('up')" @click="moveContext('top')"><ArrowUpToLine :size="16"/>移到队首</button><div class="menu-divider"/><button role="menuitem" @click="removeContextEntry"><Trash2 :size="16"/>移出队列</button></template><button v-else-if="view==='playlist'" role="menuitem" @click="removeTrack(contextMenu.track);closeMenus()"><Trash2 :size="16"/>从歌单移除</button></div>
<div v-if="queueOpen" class="queue-panel expanded-queue">
   <div class="section-heading"><h3>播放队列 <small>{{queue.length}}</small></h3><button class="icon-btn" title="关闭播放队列" @click="queueOpen=false"><X :size="18"/></button></div>
   <label class="queue-insert-switch"><input v-model="insertOnClick" type="checkbox" aria-label="点击歌曲插入当前队列"/><span>点击歌曲插入当前队列<small>{{insertOnClick?'开启：保留队列，插入并立即播放':'关闭：替换队列，旧队列存入历史'}}</small></span></label>
   <label class="queue-insert-switch resume-switch"><input v-model="restoreProgress" type="checkbox" aria-label="打开后恢复播放进度"/><span>打开后恢复播放进度<small>{{restoreProgress?'开启：恢复到上次歌曲和时间点，等待手动播放':'关闭：只恢复到上次歌曲，从头播放'}}</small></span></label>
   <div class="queue-tabs"><button :class="{active:queueTab==='current'}" @click="queueTab='current'">当前队列</button><button :class="{active:queueTab==='history'}" @click="queueTab='history'">历史队列 · {{queueSessions.length}}</button></div>
   <template v-if="queueTab==='current'"><p class="queue-name">{{currentQueue?.name||'还没有播放队列'}}</p><p v-if="currentQueue?.recovered" class="muted queue-recovery">由最近播放记录恢复；旧版本未保存的队列顺序与秒数无法还原。</p><p v-if="!queue.length" class="muted">点击一首歌或播放歌单，建立你的队列。</p><p v-if="queue.length" class="queue-sort-hint">拖动左侧手柄调整顺序，右键打开更多操作</p><div v-for="(entry,i) in queueEntries" :key="entry.entryId" :data-entry-id="entry.entryId" :class="['queue-track',{selected:currentQueue?.cursorId===entry.entryId,dragging:queueDrag?.id===entry.entryId,'drop-before':queueDrag?.over===entry.entryId&&!queueDrag?.after&&queueDrag?.id!==entry.entryId,'drop-after':queueDrag?.over===entry.entryId&&queueDrag?.after&&queueDrag?.id!==entry.entryId}]" @contextmenu.stop="openContext($event,entry.track,entry.entryId)" @dragover="queueDragOver($event,entry.entryId)" @drop="dropQueueEntry($event,entry.entryId)"><button class="queue-drag-handle" draggable="true" :aria-label="`拖动排序 ${entry.track.title}`" title="拖动排序，或右键选择上移和下移" @click.stop @dragstart.stop="beginQueueDrag($event,entry.entryId)" @dragend="endQueueDrag"><GripVertical :size="15"/></button><button class="queue-track-play" :aria-label="`播放队列第 ${i+1} 首 ${entry.track.title}`" @click="queueClick(entry)"><span class="queue-order">{{String(i+1).padStart(2,'0')}}</span><span class="queue-track-meta"><strong>{{entry.track.title}}</strong><small>{{entry.track.artist}}<em v-if="entry.inserted">插队</em><em v-if="currentQueue?.pending.includes(entry.entryId)">下一首</em><i v-if="currentQueue?.positions[entry.entryId]">已听 {{time(currentQueue.positions[entry.entryId])}}</i></small></span><Play :size="14"/></button><button class="icon-btn queue-more" :aria-label="`队列操作 ${entry.track.title}`" title="队列操作" @click.stop="openContext($event,entry.track,entry.entryId)"><MoreHorizontal :size="17"/></button></div></template>
   <template v-else><p class="muted queue-help">保留最近 10 个队列及各曲进度；重开后的恢复方式由上方开关控制。</p><div v-for="session in queueHistory" :key="session.id" :class="['queue-history-card',{selected:session.id===activeQueueId}]"><button @click="switchQueue(session.id)"><strong>{{session.name}}<b v-if="session.id===activeQueueId">当前</b></strong><span>{{session.entries.length}} 首 · {{session.entries.filter(e=>e.inserted).length}} 首插队</span><small>{{session.entries.find(e=>e.entryId===session.cursorId)?.track.title}} · {{time(session.positions[session.cursorId]||0)}}</small><small>{{new Date(session.updatedAt).toLocaleString('zh-CN')}}</small></button><button v-if="session.id!==activeQueueId" class="icon-btn" title="删除历史队列" @click="deleteQueue(session.id)"><Trash2 :size="15"/></button></div></template>
  </div>
  <footer class="player"><div class="now-playing"><button class="now-cover cover-expand" title="展开歌曲详情和歌词" :disabled="!current" @click="detailsOpen=!detailsOpen"><img v-if="current?.cover" :src="current.cover" referrerpolicy="no-referrer"/><Music2 v-else :size="25"/><span><ChevronUp :size="22"/></span></button><div class="now-meta"><strong>{{current?.title||'今天，想听点什么？'}}</strong><span>{{loading?'正在准备音频…':current?.artist||'从一首喜欢的歌开始'}}</span></div><button class="icon-btn" :class="{liked:favorite}" title="收藏" @click="like()"><Heart :size="19" :fill="favorite?'currentColor':'none'"/></button></div><div class="transport"><div class="transport-buttons"><button class="icon-btn" title="上一首" @click="next(-1)"><SkipBack :size="20" fill="currentColor"/></button><button class="play-main" :title="playing?'暂停':'播放'" @click="toggle"><LoaderCircle v-if="loading" class="spin" :size="22"/><Pause v-else-if="playing" :size="21" fill="currentColor"/><Play v-else :size="21" fill="currentColor"/></button><button class="icon-btn" title="下一首" @click="next()"><SkipForward :size="20" fill="currentColor"/></button><div class="mode-control" @click.stop><button class="icon-btn mode-toggle" :title="`播放模式：${modeInfo.label}`" aria-label="播放模式" aria-haspopup="menu" :aria-expanded="modeOpen" @click="modeOpen=!modeOpen"><component :is="modeInfo.icon" :size="18"/></button><div v-if="modeOpen" class="mode-menu" role="menu"><span>播放模式</span><button v-for="m in modes" :key="m.value" role="menuitemradio" :aria-checked="playbackMode===m.value" @click="playbackMode=m.value;modeOpen=false"><component :is="m.icon" :size="17"/>{{m.label}}</button></div></div></div><div class="timeline"><span>{{time(elapsed)}}</span><input type="range" aria-label="播放进度" min="0" :max="duration||1" :value="elapsed" :disabled="!duration" @input="seek"/><span>{{time(duration)}}</span></div></div><div class="player-extras"><span class="quality">{{current?.bvid?'BILIBILI':'NEKO AUDIO'}}</span><button :class="['icon-btn','balance-control',{enabled:balanceEnabled}]" :disabled="!current" :title="balanceEnabled?'这首歌的音量平衡已开启，点击关闭并记忆':'这首歌的音量平衡已关闭，点击开启并记忆'" aria-label="音量平衡" :aria-pressed="balanceEnabled" @click="balanceEnabled=!balanceEnabled"><AudioLines :size="18"/></button><Volume2 :size="18"/><input v-model.number="volume" type="range" min="0" max="1" step="0.01" aria-label="音量"/><label class="volume-value"><input :value="volumeDraft" type="number" min="0" max="100" step="1" aria-label="音量百分比" @input="setVolume" @blur="volumeDraft=String(volumePercent)" @keydown.enter="($event.target as HTMLInputElement).blur()"/><span>%</span></label><span class="divider"/><button :class="['icon-btn',{enabled:queueOpen}]" title="播放队列" @click="queueOpen=!queueOpen"><ListMusic :size="21"/></button></div></footer>
  <TrackDetails v-if="detailsOpen&&current" :song="current" :audio="audio" :elapsed="elapsed" :duration="duration" :playing="playing" :liked="favorite" :balance-enabled="balanceEnabled" :balance-db="balanceDb" :track-gain-db="trackGainDb" @close="detailsOpen=false" @toggle="toggle" @previous="next(-1)" @next="next()" @like="like()" @source="findSource(current)" @seek="seekSeconds" @lyrics="(text,provider)=>editCurrent({customLyrics:text,customLyricsProvider:provider})" @translation="text=>editCurrent({customTranslation:text})" @offset="ms=>editCurrent({lyricOffsetMs:ms})" @balance="balanceEnabled=$event" @track-gain="trackGainDb=$event"/>
  <audio ref="audio" crossorigin="anonymous" @play="playing=true" @pause="playbackPaused" @timeupdate="playbackTime" @durationchange="duration=Number.isFinite(audio?.duration)?audio!.duration:0" @ended="ended" @error="loading=false;playing=false;notify('音频播放失败，请重新播放以刷新地址，或选择其他音源。')"/>
  <input ref="localInput" type="file" hidden multiple accept=".mp3,.wav,.m4a,.ogg,.flac,.aac" @change="localFiles"/>
  <div v-if="modal" class="modal-backdrop" @click.self="!importing&&closeModal()"><section :class="['modal',{'source-modal':modal==='source'}]"><button class="modal-close icon-btn" title="关闭" :disabled="importing" @click="closeModal"><X :size="21"/></button>
   <template v-if="modal==='import'"><span class="modal-symbol"><ArrowDownToLine :size="25"/></span><h2>把喜欢的歌，带过来。</h2><p class="muted">先收藏歌曲，再为它们找到合适的 B 站音源。</p><div class="tabs"><button :class="{active:importMode==='link'}" @click="importMode='link'"><Link2 :size="16"/>酷狗分享链接</button><button :class="{active:importMode==='text'}" @click="importMode='text'"><ListMusic :size="16"/>歌曲清单</button></div><label>歌单名称<input v-model="importName" class="field" placeholder="给这份心动起个名字" maxlength="60"/></label><label>{{importMode==='link'?'分享文字 / 链接':'歌曲清单（每行一首）'}}<textarea v-model="importValue" :placeholder="importMode==='link'?'粘贴酷狗导出的完整分享文字或 HTTPS 链接…':'歌手 - 歌名\n歌手 - 歌名\n也可以只填写歌名'" rows="6"/></label><div class="info-box">{{importMode==='link'?'支持酷狗短链接和带 global_collection_id 的分享链接。完整读取所有分页后再保存；导入的歌曲仍需关联 B 站音源。':'导入后自动按歌手、歌名和时长匹配 B 站音源。按综合评分默认选中第一项，可随时右键更换歌源。'}}</div><button class="primary wide" :disabled="importing||!importValue.trim()" @click="importSongs"><LoaderCircle v-if="importing" class="spin" :size="17"/>{{importing?'正在完整读取歌单…':'导入到我的音乐'}}</button></template>
   <template v-else-if="modal==='theme'"><span class="modal-symbol"><Palette :size="25"/></span><h2>让音乐，换个颜色。</h2><p class="muted">更鲜明的强调色，用于按钮、选中项和当前歌词。</p><div class="theme-options"><button v-for="t in themes" :key="t.id" :class="['theme-option',{selected:theme===t.id}]" :aria-pressed="theme===t.id" @click="theme=t.id"><div class="theme-preview" :style="{color:t.accent}"><i :style="{background:t.side}"/><span><b/></span></div><strong :style="{color:t.strong}">{{t.name}}</strong><small>{{theme===t.id?'正在使用':'点击切换'}}</small></button></div></template>
   <SourcePicker v-else-if="modal==='source'&&sourceTarget" :song="sourceTarget" :destinations="lists.map(p=>({id:p.id,name:p.name}))" :default-destination="selected" @version="saveIndependentVersion" @choose="useSource" @preview="previewSource" @blocked="requireVerification" @verify="openVerification"/>
   <template v-else-if="modal==='add'"><span class="modal-symbol"><ListPlus :size="25"/></span><h2>加入歌单</h2><p class="muted">{{addTarget?.title}}</p><div class="destination-list"><button v-for="p in lists" :key="p.id" :disabled="p.tracks.some(t=>t.id===addTarget?.id)" @click="addToPlaylist(p.id)"><ListMusic :size="20"/><span>{{p.name}}<small>{{p.tracks.length}} 首歌曲</small></span><Check v-if="p.tracks.some(t=>t.id===addTarget?.id)" :size="17"/><Plus v-else :size="17"/></button></div></template>
   <RecognizeDialog v-else-if="modal==='recognize'" @search="text=>{closeModal();target=null;doSearch(text)}"/>
   <template v-else-if="modal==='create'"><span class="modal-symbol"><ListMusic :size="25"/></span><h2>留一个位置给好音乐。</h2><p class="muted">创建一份属于你的歌单。</p><form @submit.prevent="createList"><label>歌单名称<input v-model="newName" class="field" placeholder="例如：下班路上的单曲循环" maxlength="60" autofocus/></label><button class="primary wide" :disabled="!newName.trim()">创建歌单</button></form></template>
   <template v-else-if="modal==='login'">
    <span class="modal-symbol"><Headphones :size="25"/></span><h2>连接你的 B 站。</h2><p class="muted">选择你习惯的方式，让好音乐继续。</p>
    <div class="tabs"><button :class="{active:loginMethod==='web'}" :disabled="webBusy" @click="chooseLogin('web')">密码 / 短信登录</button><button :class="{active:loginMethod==='qr'}" :disabled="webBusy" @click="chooseLogin('qr')">扫码登录</button></div>
    <template v-if="loginMethod==='web'"><div class="web-login-illustration"><Headphones :size="36"/><span>BILIBILI · 官方网页登录</span></div><p class="muted">将在独立窗口打开 B 站官方登录页面，可使用页面提供的账号密码或短信验证码登录，也可完成官方安全验证。</p><button class="primary wide" :disabled="webBusy" @click="openWebLogin"><LoaderCircle v-if="webBusy" class="spin" :size="17"/>打开 B 站官方登录</button><p v-if="webHint" class="recognize-message" role="status">{{webHint}}</p></template>
    <template v-else><div class="qr"><LoaderCircle v-if="qrBusy" class="spin" :size="32"/><img v-else-if="qrSvg" :src="'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(qrSvg)" alt="B 站登录二维码"/></div><p class="qr-hint">{{qrHint}}</p><button class="secondary wide" :disabled="qrBusy" @click="startLogin">刷新二维码</button></template>
    <div class="info-box">密码和验证码只在 B 站官方页面填写，本应用不读取或保存。连接成功后，仅将登录凭据保存在 Windows 凭据管理器中；可随时退出清除。</div>
   </template>
   <template v-else-if="modal==='account'"><span class="modal-symbol"><Check :size="25"/></span><h2>{{user?.name}}</h2><p class="muted">你的 B 站账号已连接。</p><div class="info-box">歌单保存在本机，退出账号不会删除歌单。受限资源仍取决于账号的实际访问权限。</div><button class="secondary wide" @click="signOut"><LogOut :size="17"/>退出并清除本机凭据</button></template>
   <template v-else-if="modal==='delete'"><span class="modal-symbol"><Trash2 :size="25"/></span><h2>删除「{{active.name}}」？</h2><p class="muted">会移除本地歌单及其中的歌曲记录，不影响其他歌单。</p><button class="primary wide danger" @click="deleteList">确认删除歌单</button></template>
  </section></div>
 </div>
</template>
